export const chatWithAI = async (chatMessage: ChatMessage, options?: RequestInit): Promise<ChatResponse> => {

  return customFetch<ChatResponse>(getChatWithAIUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(
      chatMessage,)
  }
);}




export const getChatWithAIMutationOptions = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof chatWithAI>>, TError,{data: BodyType<ChatMessage>}, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof chatWithAI>>, TError,{data: BodyType<ChatMessage>}, TContext> => {

const mutationKey = ['chatWithAI'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof chatWithAI>>, {data: BodyType<ChatMessage>}> = (props) => {
          const {data} = props ?? {};

          return  chatWithAI(data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type ChatWithAIMutationResult = NonNullable<Awaited<ReturnType<typeof chatWithAI>>>
    export type ChatWithAIMutationBody = BodyType<ChatMessage>
    export type ChatWithAIMutationError = ErrorType<unknown>

